WITH filtered AS (SELECT *, CASE WHEN cost >= 97 THEN 'High' WHEN cost >= 14 THEN 'Medium' ELSE 'Low' END AS cost_tier FROM shipments WHERE carrier IS DISTINCT FROM 'Flash' AND order_id IS NOT NULL), with_windows AS (SELECT id, carrier, shipped_date, delivered_date, status, cost_tier, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share, AVG(cost) OVER (PARTITION BY status, order_id ORDER BY cost ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS cost_avg_6, PERCENT_RANK() OVER (PARTITION BY status ORDER BY cost ASC) AS cost_percent_rank FROM filtered), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY cost_percent_rank DESC NULLS FIRST, id ASC) AS rn FROM with_windows QUALIFY rn = 1), base AS (SELECT *, CASE WHEN cost_share >= 0.82 THEN 'High' WHEN cost_share >= 0.35 THEN 'Medium' ELSE 'Low' END AS cost_share_tier, LOWER(status) AS status_lower, COALESCE(carrier, 'UNKNOWN') AS carrier_filled FROM deduped WHERE delivered_date > DATE '2023-04-15' AND carrier IS NOT NULL), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY shipped_date DESC, id ASC) AS latest_rank FROM base QUALIFY latest_rank = 1) SELECT id, carrier, shipped_date, delivered_date, cost_share, cost_avg_6, rn, cost_share_tier, latest_rank, SUM(cost_percent_rank) OVER w_running AS last7_sum_cost_percent_rank, AVG(cost_percent_rank) OVER w_running AS last7_avg_cost_percent_rank, COUNT(cost_percent_rank) OVER w_running AS last7_count_cost_percent_rank, MAX(cost_percent_rank) OVER w_running AS last7_max_cost_percent_rank, SUM(cost_share) OVER (PARTITION BY carrier) AS carrier_sum_cost_share FROM latest WINDOW w_running AS (PARTITION BY carrier, status ORDER BY cost_share ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
